 public const APPROVER_GROUP='Letterhead Document Approver';
 public function __construct(private IDBConnection $db,private IGroupManager $groups,private IUserManager $users,private AccountService $accounts,private LetterheadStorage $storage,private LetterheadPdfService $pdf,private CampaignRecipientResolver $resolver,private FileService $files,private PdfMetadataExtractor $metadata,private RequestSignatureService $requests,private FileMapper $fileMapper,private LetterheadNotificationService $notifications) {}
 private function active(?IUser $u): void {if(!$u||!$u->isEnabled())throw new NotPermittedException('Sign in with an active account.');}
 public function admin(?IUser $u): bool {return $u&&$u->isEnabled()&&$this->groups->isInGroup($u->getUID(),'admin');}
