 private function insert(string $table,array $values): int {$q=$this->db->getQueryBuilder();$q->insert($table);foreach($values as $k=>$v)$q->setValue($k,$q->createNamedParameter($v,$v===null?IQueryBuilder::PARAM_NULL:(is_int($v)?IQueryBuilder::PARAM_INT:IQueryBuilder::PARAM_STR)));$q->executeStatement();return (int)$q->getLastInsertId();}
 private function event(array $d,string $actor,string $action,array $details=[]): void {$this->insert('libresign_letter_event',['document_id'=>(int)$d['id'],'actor'=>$actor,'action'=>$action,'document_hash'=>$d['composed_hash'],'details'=>json_encode($details,JSON_THROW_ON_ERROR),'created_at'=>time()]);}
 public function templates(IUser $u): array {$this->active($u);$q=$this->db->getQueryBuilder();$q->select('id','name','active','created_at')->from('libresign_letterhead');if(!$this->admin($u))$q->where('active = 1');return $q->orderBy('name','ASC')->executeQuery()->fetchAll();}
 public function addTemplate(IUser $u,string $name,string $base64): array {
  if(!$this->admin($u))throw new NotPermittedException('Only administrators can manage shared letterheads.');$name=CampaignDefinition::text($name,200,'letterhead name');$content=CampaignDefinition::pdf($base64);$this->files->validateFileContent($content,'letterhead.pdf','pdf');$node=$this->storage->write($content);$this->metadata->setFile($node);$dims=$this->metadata->getPageDimensions();if(count($dims['d']??[])!==1)throw new \InvalidArgumentException('Upload a one-page PDF letterhead.');
  $id=$this->insert('libresign_letterhead',['name'=>$name,'filename'=>$node->getName(),'hash'=>hash('sha256',$content),'owner_uid'=>$u->getUID(),'active'=>1,'created_at'=>time()]);return ['id'=>$id,'name'=>$name,'active'=>1];
 }
 public function templateState(IUser $u,int $id,bool $active): array {if(!$this->admin($u))throw new NotPermittedException('Administrator access required.');$this->record('libresign_letterhead',$id);$q=$this->db->getQueryBuilder();$q->update('libresign_letterhead')->set('active',$q->createNamedParameter($active?1:0,IQueryBuilder::PARAM_INT))->where($q->expr()->eq('id',$q->createNamedParameter($id,IQueryBuilder::PARAM_INT)))->executeStatement();return ['id'=>$id,'active'=>$active];}
 public function people(IUser $u,string $search,bool $approvers=false): array {$this->active($u);$search=CampaignDefinition::text($search,200,'search',false);$found=$approvers?($this->groups->get(self::APPROVER_GROUP)?->searchUsers($search,30,0)??[]):$this->users->searchDisplayName($search,20,0);if(!$approvers&&filter_var($search,FILTER_VALIDATE_EMAIL))$found=[...$this->users->getByEmail($search),...$found];$out=[];foreach($found as $person)if($person->isEnabled()&&filter_var($person->getEMailAddress(),FILTER_VALIDATE_EMAIL)&&(!$approvers||$person->getUID()!==$u->getUID()))$out[$person->getUID()]=['uid'=>$person->getUID(),'name'=>$person->getDisplayName(),'email'=>$person->getEMailAddress()];return array_values($out);}
 public function resolve(IUser $u,array $input): array {$this->creator($u);return $this->resolver->resolve($input);}
 public function list(IUser $u,int $page=1,string $view='mine'): array {
  $this->active($u);if(!in_array($view,['mine','approvals','all'],true))throw new \InvalidArgumentException('Invalid document view.');$q=$this->db->getQueryBuilder();$q->from('libresign_letter_doc');
  if($view==='approvals') {if(!$this->approver($u))throw new NotPermittedException('Approver access required.');$q->where($q->expr()->eq('approver_uid',$q->createNamedParameter($u->getUID())));}
  elseif($view==='all') {if(!$this->admin($u))throw new NotPermittedException('Administrator access required.');}
  else $q->where($q->expr()->eq('owner_uid',$q->createNamedParameter($u->getUID())));
  $count=clone $q;$total=(int)$count->select($count->func()->count('id'))->executeQuery()->fetchOne();$rows=$q->select('*')->orderBy('id','DESC')->setMaxResults(25)->setFirstResult((max(1,$page)-1)*25)->executeQuery()->fetchAll();
  return ['data'=>array_map(fn($r)=>$this->present($r),$rows),'total'=>$total,'canApprove'=>$this->approver($u),'isAdmin'=>$this->admin($u),'canCreate'=>$this->accounts->canRequestSign($u)];
 }
 private function present(array $d): array {return ['id'=>(int)$d['id'],'name'=>$d['name'],'state'=>$d['state'],'owner'=>['uid'=>$d['owner_uid'],'name'=>$this->users->get($d['owner_uid'])?->getDisplayName()??$d['owner_uid']],'templateId'=>(int)$d['template_id'],'approver'=>$d['approver_uid']?['uid'=>$d['approver_uid'],'name'=>$this->users->get($d['approver_uid'])?->getDisplayName()??$d['approver_uid']]:null,'createdAt'=>(int)$d['created_at'],'approvedAt'=>$d['approved_at']?(int)$d['approved_at']:null,'revision'=>(int)$d['revision'],'reason'=>$d['reason'],'hash'=>$d['composed_hash'],'recipients'=>json_decode($d['recipients'],true,512,JSON_THROW_ON_ERROR),'pages'=>count(json_decode($d['pdf_metadata'],true,512,JSON_THROW_ON_ERROR)['d']??[]),'fileId'=>$d['file_id']?(int)$d['file_id']:null];}
 public function get(IUser $u,int $id): array {$d=$this->authorised($u,$id);$q=$this->db->getQueryBuilder();$events=$q->select('*')->from('libresign_letter_event')->where($q->expr()->eq('document_id',$q->createNamedParameter($id,IQueryBuilder::PARAM_INT)))->orderBy('id','DESC')->executeQuery()->fetchAll();$warning='';foreach($events as $event)if(in_array($event['action'],['notification_sent','notification_failed'],true)){$warning=$event['action']==='notification_failed'?'The review action was saved, but its email notification could not be sent. The document is still available in Letterheads.':'';break;}return $this->present($d)+['events'=>$events,'notificationWarning'=>$warning];}
 public function authorised(IUser $u,int $id): array {$this->active($u);$d=$this->record('libresign_letter_doc',$id);if($d['owner_uid']!==$u->getUID()&&!$this->admin($u)&&!($d['approver_uid']===$u->getUID()&&$this->approver($u)))throw new NotPermittedException('Document unavailable to this account.');return $d;}
 public function create(IUser $u,array $input): array {
  $this->creator($u);$name=CampaignDefinition::text($input['name']??'',200,'document name');$template=$this->record('libresign_letterhead',(int)($input['templateId']??0));if(!(int)$template['active'])throw new \InvalidArgumentException('Choose an active letterhead.');
  $recipients=$this->resolver->resolveMany($input['recipients']??[]);if(!$recipients||count($recipients)>20)throw new \InvalidArgumentException('Select between one and twenty signers.');$external=(bool)array_filter($recipients,fn($r)=>$r['uid']===null);$approverUid=$input['approverUid']??null;
  if($external&&(!is_string($approverUid)||$approverUid===$u->getUID()||!$this->approver($this->users->get($approverUid))))throw new \InvalidArgumentException('Choose another active user from Letterhead Document Approver.');
  $layer=$input['layer']??'front';if(!in_array($layer,['front','behind'],true))throw new \InvalidArgumentException('Invalid letterhead placement.');$source=CampaignDefinition::pdf($input['pdf']??'');$this->files->validateFileContent($source,'document.pdf','pdf');$sourceNode=$this->storage->write($source);$content=$this->pdf->compose($source,$this->storage->verified($template['filename'],$template['hash'])->getContent(),$layer);$node=$this->storage->write($content);$this->metadata->setFile($node);$dimensions=$this->metadata->getPageDimensions();
  $id=$this->insert('libresign_letter_doc',['owner_uid'=>$u->getUID(),'name'=>$name,'template_id'=>(int)$template['id'],'source_file'=>$sourceNode->getName(),'composed_file'=>$node->getName(),'composed_hash'=>hash('sha256',$content),'template_hash'=>$template['hash'],'state'=>$external?'draft':'approved','layer'=>$layer,'approver_uid'=>$external?$approverUid:null,'recipients'=>json_encode($recipients,JSON_THROW_ON_ERROR),'pdf_metadata'=>json_encode($dimensions,JSON_THROW_ON_ERROR),'created_at'=>time(),'approved_at'=>$external?null:time(),'revision'=>1]);$d=$this->record('libresign_letter_doc',$id);$this->event($d,$u->getUID(),'created',['externalApprovalRequired'=>$external,'templateHash'=>$template['hash']]);return $this->get($u,$id);
 }
 public function submit(IUser $u,int $id,int $revision): array {$d=$this->authorised($u,$id);if($d['owner_uid']!==$u->getUID()||$d['state']!=='draft')throw new NotPermittedException('Only the creator can submit this draft.');if(!$this->approver($this->users->get($d['approver_uid'])))throw new \InvalidArgumentException('Selected approver no longer has the required role.');$this->storage->verified($d['composed_file'],$d['composed_hash']);$this->transition($d,$revision,['state'=>'pending','submitted_at'=>time()],$u->getUID(),'submitted');$delivery=$this->notifications->send($d,$d['approver_uid'],'submitted');$this->event($d,$u->getUID(),'notification_'.$delivery);return $this->get($u,$id);}
 public function decide(IUser $u,int $id,int $revision,bool $approve,string $reason): array {$d=$this->authorised($u,$id);if(!$this->approver($u)||$d['approver_uid']!==$u->getUID()||$d['owner_uid']===$u->getUID()||$d['state']!=='pending')throw new NotPermittedException('Only the selected approver can decide this pending document.');$reason=CampaignDefinition::text($reason,2000,'approval comments',!$approve);$this->storage->verified($d['composed_file'],$d['composed_hash']);$this->transition($d,$revision,['state'=>$approve?'approved':'rejected','approved_at'=>$approve?time():null,'reason'=>$reason],$u->getUID(),$approve?'approved':'rejected');$delivery=$this->notifications->send($d,$d['owner_uid'],$approve?'approved':'rejected');$this->event($d,$u->getUID(),'notification_'.$delivery);return $this->get($u,$id);}
 private function transition(array $d,int $revision,array $values,string $actor,string $action): void {$this->db->beginTransaction();try{$q=$this->db->getQueryBuilder();$q->update('libresign_letter_doc')->where($q->expr()->eq('id',$q->createNamedParameter((int)$d['id'],IQueryBuilder::PARAM_INT)))->andWhere($q->expr()->eq('revision',$q->createNamedParameter($revision,IQueryBuilder::PARAM_INT)))->andWhere($q->expr()->eq('state',$q->createNamedParameter($d['state'])));foreach($values+['revision'=>$revision+1] as $k=>$v)$q->set($k,$q->createNamedParameter($v,$v===null?IQueryBuilder::PARAM_NULL:(is_int($v)?IQueryBuilder::PARAM_INT:IQueryBuilder::PARAM_STR)));if($q->executeStatement()!==1)throw new \RuntimeException('The document changed in another window. Refresh before continuing.',409);$this->event($d,$actor,$action,$values);$this->db->commit();}catch(\Throwable $e){$this->db->rollBack();throw $e;}}
 public function preview(IUser $u,int $id,int $page): string {$d=$this->authorised($u,$id);$pages=count(json_decode($d['pdf_metadata'],true,512,JSON_THROW_ON_ERROR)['d']??[]);if($page<1||$page>$pages)throw new \InvalidArgumentException('Preview page does not exist.');return $this->pdf->preview($this->storage->verified($d['composed_file'],$d['composed_hash'])->getContent(),$page);}
 public function download(IUser $u,int $id): \OCP\Files\File {$d=$this->authorised($u,$id);if($d['state']!=='approved')throw new NotPermittedException('The letterheaded PDF can be downloaded or printed only after approval.');return $this->storage->verified($d['composed_file'],$d['composed_hash']);}
 public function prepareRequest(IUser $u,int $id): array {
  $this->creator($u);$d=$this->authorised($u,$id);if($d['owner_uid']!==$u->getUID()||$d['state']!=='approved')throw new NotPermittedException('Approval is required before preparing signing.');if($d['file_id']){try{$file=$this->fileMapper->getById((int)$d['file_id']);return ['id'=>$file->getId(),'uuid'=>$file->getUuid()];}catch(DoesNotExistException){$q=$this->db->getQueryBuilder();$q->update('libresign_letter_doc')->set('file_id',$q->createNamedParameter(null,IQueryBuilder::PARAM_NULL))->where($q->expr()->eq('id',$q->createNamedParameter($id,IQueryBuilder::PARAM_INT)))->andWhere($q->expr()->eq('file_id',$q->createNamedParameter((int)$d['file_id'],IQueryBuilder::PARAM_INT)))->executeStatement();$d=$this->record('libresign_letter_doc',$id);}}
  $signers=[];foreach(json_decode($d['recipients'],true,512,JSON_THROW_ON_ERROR) as $i=>$r){$current=$this->resolver->resolve($r);if($current['recipient_key']!==$r['recipient_key'])throw new \RuntimeException('A signer identity changed. Prepare a new document for approval.');$signers[]=['displayName'=>$r['name'],'notify'=>0,'signingOrder'=>$i+1,'identifyMethods'=>[['method'=>$r['uid']!==null?'account':'email','value'=>$r['uid']??$r['email']]]];}
  $node=$this->storage->verified($d['composed_file'],$d['composed_hash']);$data=['name'=>$d['name'],'file'=>['base64'=>base64_encode($node->getContent())],'userManager'=>$u,'status'=>0,'settings'=>[],'signatureFlow'=>'ordered_numeric','signers'=>$signers];LetterheadUploadPolicy::withApproval($id,$d['composed_hash'],fn()=>$this->requests->validateNewRequestToFile($data));$data['file']=['fileNode'=>$this->storage->write($node->getContent())];
  $this->db->beginTransaction();try{$q=$this->db->getQueryBuilder();$q->update('libresign_letter_doc')->set('revision',$q->createNamedParameter((int)$d['revision']+1,IQueryBuilder::PARAM_INT))->where($q->expr()->eq('id',$q->createNamedParameter($id,IQueryBuilder::PARAM_INT)))->andWhere($q->expr()->eq('revision',$q->createNamedParameter((int)$d['revision'],IQueryBuilder::PARAM_INT)))->andWhere($q->expr()->isNull('file_id'));if($q->executeStatement()!==1)throw new \RuntimeException('Another window is preparing this request. Refresh.',409);
   $file=LetterheadUploadPolicy::withApproval($id,$d['composed_hash'],fn()=>$this->requests->save($data));$meta=$file->getMetadata()??[];$meta['letterhead']=['id'=>$id,'sourceHash'=>$d['composed_hash'],'templateId'=>(int)$d['template_id'],'approvedAt'=>$d['approved_at'],'approverUid'=>$d['approver_uid']];$file->setMetadata($meta);$this->fileMapper->update($file);$q=$this->db->getQueryBuilder();$q->update('libresign_letter_doc')->set('file_id',$q->createNamedParameter($file->getId(),IQueryBuilder::PARAM_INT))->where($q->expr()->eq('id',$q->createNamedParameter($id,IQueryBuilder::PARAM_INT)))->executeStatement();$this->event($d,$u->getUID(),'signing_prepared',['fileId'=>$file->getId()]);$this->db->commit();return ['id'=>$file->getId(),'uuid'=>$file->getUuid()];
  }catch(\Throwable $e){$this->db->rollBack();throw $e;}
 }
 public function canReleaseFile(File $f): bool {$meta=($f->getMetadata()??[])['letterhead']??null;if($meta===null)return true;if(!is_array($meta)||empty($meta['id']))return false;try{$d=$this->record('libresign_letter_doc',(int)$meta['id']);return $d['state']==='approved'&&(int)$d['file_id']===$f->getId()&&$d['owner_uid']===$f->getUserId()&&hash_equals($d['composed_hash'],(string)($meta['sourceHash']??''));}catch(DoesNotExistException){return false;}}
