 public function assertSignerEdit(File $f,array $input): void {
  if(empty(($f->getMetadata()??[])['letterhead']))return;$this->assertRelease($f);if(!array_key_exists('signers',$input))return;$d=$this->record('libresign_letter_doc',(int)$f->getMetadata()['letterhead']['id']);$approved=[];foreach(json_decode($d['recipients'],true,512,JSON_THROW_ON_ERROR) as $r)$approved[]=($r['uid']!==null?'account:'.$r['uid']:'email:'.strtolower($r['email']));$actual=[];foreach($input['signers'] as $signer){if(count($signer['identifyMethods']??[])!==1)throw new NotPermittedException('The approved signer identities are fixed.');foreach($signer['identifyMethods']??[] as $m){$method=$m['method']??'';if(!in_array($method,['account','email'],true))throw new NotPermittedException('The approved signer identities are fixed.');$actual[]=$method.':'.($method==='email'?strtolower($m['value']??''):($m['value']??''));}}sort($approved);sort($actual);if($approved!==$actual)throw new NotPermittedException('The approved signer list is fixed. Create a new letterhead document to change recipients.');
 }
